import {validateOnline} from './multiplayer.js';
import {validate,validateStructure,ensureLogos,ensurePortraits} from './engine.js';
let connection;
function database(){return connection??=new Promise((resolve,reject)=>{const request=indexedDB.open('SlimballManager',1);request.onupgradeneeded=()=>{request.result.createObjectStore('games',{keyPath:'id'});request.result.createObjectStore('backups',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>{connection=null;reject(request.error);};});}
const requestValue=req=>new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
const done=tx=>new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('save_failed'));});
export async function save(s){validate(s);validateOnline(s,true);const envelope={id:s.id,format:'SlimballManager',version:1,savedAt:Date.now(),state:JSON.parse(JSON.stringify(s))};const db=await database(),tx=db.transaction(['games','backups'],'readwrite'),finish=done(tx),games=tx.objectStore('games');const old=games.get(s.id);old.onsuccess=()=>{if(old.result)tx.objectStore('backups').put(old.result);games.put(envelope);};await finish;return true;}
export function decode(text){if(text.length>30000000)throw Error('file_large');let d;try{d=JSON.parse(text);}catch{throw Error('invalid_save');}if(!d||d.format!=='SlimballManager'||d.version!==1)throw Error('invalid_save');try{validate(d.state);validateStructure(d.state);validateOnline(d.state,true);for(const live of Object.values(d.state.online?.lives||{}))validateStructure({...d.state,live});}catch{throw Error('invalid_save');}return ensurePortraits(ensureLogos(d.state));}
export async function load(id,backup=false){const db=await database(),d=await requestValue(db.transaction(backup?'backups':'games').objectStore(backup?'backups':'games').get(id));if(!d)throw Error('invalid_save');return decode(JSON.stringify(d));}
export async function list(){const db=await database(),all=await requestValue(db.transaction('games').objectStore('games').getAll());return all.map(d=>{try{return {id:d.id,name:d.state.teams.find(t=>t.id===d.state.user).name,season:d.state.season,savedAt:d.savedAt,mode:d.state.mode};}catch{return {id:d.id,name:'?',season:'?',savedAt:0,corrupt:true};}}).sort((a,b)=>b.savedAt-a.savedAt);}
export async function remove(id){const db=await database(),tx=db.transaction(['games','backups'],'readwrite'),finish=done(tx);tx.objectStore('games').delete(id);tx.objectStore('backups').delete(id);await finish;}
export function download(s){const blob=new Blob([JSON.stringify({format:'SlimballManager',version:1,savedAt:Date.now(),state:s})],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`slimball-saison-${s.season}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
